const ID_PREFIX: &str = "postgres_integration_test_";

// Generates a name for a test index based on the test context.
fn index_name(ctx: &Context) -> String {
    format!("{}_{}", ID_PREFIX, ctx.name)
}

/// Test helper to create a sample index
fn create_sample_index(name: &str) -> Index {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap();
    
    Index {
        name: name.to_string(),
        description: "Test index".to_string(),
        max_bulk_operations: 100,
        max_key_length: 256,
        max_value_length: 1024,
        max_kv_pairs_per_context: 50,
        hash_algorithm: udex_api::index::HashAlgorithm::Sha1 as i32, // Use the enum value directly
        created_at: Some(udex_api::protobuf::Timestamp {
            seconds: now.as_secs() as i64,
            nanos: now.subsec_nanos() as i32,
        }),
        created_by: "test_user".to_string(),
        updated_at: None,
        updated_by: None,
    }
}

/// Test helper to create a sample context
fn create_sample_context(hash: &str) -> UdexContext {
    UdexContext {
        hash: hash.to_string(),
        pairs: vec![
            KeyValuePair {
                key: "name".to_string(),
                value: Some(Value {
                    value: Some(udex_api::entry::value::Value::StringValue("test_value".to_string())),
                }),
                kek_id: None,
            },
            KeyValuePair {
                key: "count".to_string(),
                value: Some(Value {
                    value: Some(udex_api::entry::value::Value::IntValue(42)),
                }),
                kek_id: None,
            },
        ],
        dek: None,
        kek_id: None,
    }
}

