/// Tests deleting an entry between a key and context.
/// Verifies that entries can be successfully removed and that
/// the context no longer has any associated keys after deletion.
#[rstest]
#[tokio_shared_rt::test]
async fn test_delete_entry(
    #[context] ctx: Context,
) {
    let data = data(false).await;
    let datastore = &data.0;
    let pool = &data.1;
    let idx_name = index_name(&ctx);

    let index = create_sample_index(&idx_name);
    let context = create_sample_context("test_hash_5");
    let key = Uuid::new_v4();

    // Create prerequisite data
    datastore
        .create_index(index)
        .await
        .expect("Failed to create index");

    // Create entry using datastore method
    let entry = Entry {
        key,
        context: context.clone(),
        index_name: idx_name.clone(),
    };
    
    datastore
        .create_entry(entry)
        .await
        .expect("Failed to create entry");

    // Verify entry exists before deletion
    let retrieved_entry = datastore
        .get_entry_by_key(key)
        .await
        .expect("Failed to get entry before deletion");
    assert_eq!(retrieved_entry.key, key);
    assert_eq!(retrieved_entry.context.hash, context.hash);

    // Test deleting entry
    let result = datastore.delete_entry(key).await;
    assert!(result.is_ok(), "Deleting entry should succeed");

    // Verify the entry was deleted
    let entries = datastore
        .get_entries_by_context(&context.hash)
        .await
        .expect("Failed to get entries");
    assert_eq!(entries.len(), 0);

    // Create two entries for the same context with different keys.
    let key2 = Uuid::new_v4();
    let entry2 = Entry {
        key: key2,
        context: context.clone(),
        index_name: idx_name.clone(),
    };
    datastore
        .create_entry(entry2)
        .await
        .expect("Failed to create second entry");
    let key3 = Uuid::new_v4();
    let entry3 = Entry {
        key: key3,
        context: context.clone(),
        index_name: idx_name.clone(),
    };
    datastore
        .create_entry(entry3)
        .await
        .expect("Failed to create third entry");

    // Verify that if we delete the entry for key2 the entry for key still exists.
    let result = datastore.delete_entry(key2).await;
    assert!(result.is_ok(), "Deleting entry should succeed"); 
    let entries = datastore
        .get_entries_by_context(&context.hash)
        .await
        .expect("Failed to get entries after deletion");
    assert_eq!(entries.len(), 1, "Expected 1 entry remaining for context after deletion");
    assert_eq!(entries[0].key, key3, "Remaining entry should be the one with key3");
    assert_eq!(entries[0].context.hash, context.hash, "Remaining entry should have the same context hash");

    // Verify that if we now delete the last entry for the context it is also deleted.
    let result = datastore.delete_entry(key3).await;
    assert!(result.is_ok(), "Deleting last entry should succeed");
    let entries = datastore
        .get_entries_by_context(&context.hash)
        .await
        .expect("Failed to get entries after deleting last entry");
    assert_eq!(entries.len(), 0, "Expected no entries remaining for context after deleting last entry"); 

    // Verify the context has also been deleted by using a direct sqlx query.
    let context_exists: bool = sqlx::query_scalar("SELECT EXISTS(SELECT 1 FROM context WHERE hash = $1)")
        .bind(&context.hash)
        .fetch_one(&**pool)
        .await
        .expect("Failed to check if context exists");
    assert!(!context_exists, "Context should be deleted after last entry is removed");
}

