/// Tests updating an index's mutable fields.
/// Verifies that index descriptions can be updated and that
/// the updated values are correctly persisted and retrieved.
#[rstest]
#[tokio_shared_rt::test]
async fn test_update_index(
    #[context] ctx: Context,
) {
    let data = data(false).await;
    let datastore = &data.0;
    let idx_name = index_name(&ctx);

    let index = create_sample_index(&idx_name);

    // Create index
    datastore
        .create_index(index.clone())
        .await
        .expect("Failed to create index");

    // Update the index description
    let new_description = Some("Updated test index description".to_string());
    let new_description_value = new_description.clone().unwrap_or_default();
    let update = IndexUpdate {
        description: new_description.clone(),
        max_bulk_operations: None,
        max_key_length: None,
        max_value_length: None,
        max_kv_pairs_per_context: None,
        hash_algorithm: None,
    };
    let updated_index = datastore
        .update_index(&idx_name, update, "test_update_index")
        .await
        .expect("Failed to update index");

    // Verify the update
    assert_eq!(updated_index.name, index.name);
    assert_eq!(updated_index.description, new_description_value);
    assert_eq!(updated_index.max_bulk_operations, index.max_bulk_operations);
    assert_eq!(updated_index.hash_algorithm, index.hash_algorithm);
    assert_eq!(updated_index.created_by, index.created_by);
    assert!(updated_index.created_at.is_some());

    // Verify by getting the index again
    let retrieved_index = datastore
        .get_index(&idx_name)
        .await
        .expect("Failed to get updated index");
    assert_eq!(retrieved_index.description, new_description_value);

    // Test updating to empty description
    let empty_description_update = IndexUpdate {
        description: Some("".to_string()),
        max_bulk_operations: None,
        max_key_length: None,
        max_value_length: None,
        max_kv_pairs_per_context: None,
        hash_algorithm: None,
    };
    let updated_to_empty = datastore
        .update_index(&idx_name, empty_description_update, "test_update_index")
        .await
        .expect("Failed to update index to empty description");
    assert_eq!(updated_to_empty.description, "");

    // Test all mutable fields can be updated
    let full_update = IndexUpdate {
        description: Some("Full update test index".to_string()),
        max_bulk_operations: Some(200),
        max_key_length: Some(512),
        max_value_length: Some(2048),
        max_kv_pairs_per_context: Some(100),
        hash_algorithm: Some(udex_api::index::HashAlgorithm::Sha1 as i32),
    };
    let updated_full_index = datastore
        .update_index(&idx_name, full_update, "test_full_update_index")
        .await
        .expect("Failed to fully update index");
    assert_eq!(updated_full_index.name, index.name);
    assert_eq!(updated_full_index.description, "Full update test index");
    assert_eq!(updated_full_index.max_bulk_operations, 200);
    assert_eq!(updated_full_index.max_key_length, 512);
    assert_eq!(updated_full_index.max_value_length, 2048);
    assert_eq!(updated_full_index.max_kv_pairs_per_context, 100);
    assert_eq!(updated_full_index.hash_algorithm, udex_api::index::HashAlgorithm::Sha1 as i32);

    // Test updating no fields throws an error
    let no_update = IndexUpdate {
        description: None,
        max_bulk_operations: None,
        max_key_length: None,
        max_value_length: None,
        max_kv_pairs_per_context: None,  
        hash_algorithm: None,
    };
    let no_update_result = datastore.update_index(&idx_name, no_update, "test_update_index").await;
    assert!(no_update_result.is_err(), "Updating index with no changes should fail");
    if let Err(error) = no_update_result {
        match error {
            udex_datastore::Error::InvalidIndexUpdate(_) => {
                // This is expected
            }
            _ => panic!("Expected InvalidIndexUpdate error, got: {:?}", error),
        }
    }
}

/// Tests listing all indices.
/// Verifies that all created indices are returned in the list
/// and that the list is properly ordered by name.
#[rstest]
#[tokio_shared_rt::test]
async fn test_list_indices(
    #[context] ctx: Context,
) {
    let data = data(false).await;
    let datastore = &data.0;
    let idx_name = index_name(&ctx);

    // Create multiple indices
    let index1 = create_sample_index(&format!("{}_list_1", idx_name));
    let index2 = create_sample_index(&format!("{}_list_2", idx_name));
    let index3 = create_sample_index(&format!("{}_list_3", idx_name));

    datastore.create_index(index1.clone()).await.expect("Failed to create index 1");
    datastore.create_index(index2.clone()).await.expect("Failed to create index 2");
    datastore.create_index(index3.clone()).await.expect("Failed to create index 3");

    // List all indices
    let indices = datastore
        .list_indices()
        .await
        .expect("Failed to list indices");

    // Find our test indices in the list
    let our_indices: Vec<_> = indices
        .iter()
        .filter(|idx| idx.name.contains(&format!("{}_list_", idx_name)))
        .collect();

    assert_eq!(our_indices.len(), 3);
    assert!(our_indices.iter().any(|idx| idx.name == index1.name));
    assert!(our_indices.iter().any(|idx| idx.name == index2.name));
    assert!(our_indices.iter().any(|idx| idx.name == index3.name));

    // Verify ordering (should be sorted by name)
    for i in 1..our_indices.len() {
        assert!(our_indices[i-1].name <= our_indices[i].name);
    }
}


